export type UserRole = 'user' | 'moderator' | 'admin';
export type VideoVisibility = 'public' | 'unlisted' | 'private';
export type VideoProcessingStatus = 'uploading' | 'queued' | 'processing' | 'ready' | 'failed';
export type VideoModerationStatus = 'pending' | 'approved' | 'hidden';

export interface User {
  id: string;
  email: string;
  username: string;
  full_name: string | null;
  avatar_url: string | null;
  role: UserRole;
  is_active: boolean;
  created_at: string;
}

export interface Channel {
  id: string;
  user_id: string;
  handle: string;
  name: string;
  description: string;
  avatar_url: string | null;
  banner_url: string | null;
  subscribers_count: number;
  created_at: string;
  is_subscribed?: boolean;
}

export interface Video {
  id: string;
  channel_id: string;
  title: string;
  description: string;
  video_url: string;
  thumbnail_url: string | null;
  duration: number;
  views_count: number;
  likes_count: number;
  dislikes_count: number;
  visibility: VideoVisibility;
  processing_status: VideoProcessingStatus;
  moderation_status: VideoModerationStatus;
  created_at: string;
  channel?: Channel;
  user_reaction?: 'like' | 'dislike' | null;
  is_owner?: boolean;
}

export interface VideoAccessGrant {
  id: string;
  video_id: string;
  user_id: string;
  user?: User;
  created_at: string;
}

export interface Comment {
  id: string;
  video_id: string;
  user_id: string;
  content: string;
  created_at: string;
  user?: User;
  can_delete?: boolean;
}

export interface Playlist {
  id: string;
  channel_id: string;
  title: string;
  description: string;
  visibility: VideoVisibility;
  created_at: string;
  items?: PlaylistItem[];
}

export interface PlaylistItem {
  id: string;
  playlist_id: string;
  video_id: string;
  position: number;
  added_at: string;
  video?: Video;
}

export interface Report {
  id: string;
  video_id: string;
  reporter_id: string;
  reason: string;
  details: string;
  status: 'pending' | 'reviewed' | 'dismissed';
  created_at: string;
  reporter?: User;
  video?: Video;
}

export interface ModerationAction {
  id: string;
  moderator_id: string;
  video_id: string;
  action: 'hide' | 'restore' | 'delete';
  reason: string;
  created_at: string;
  moderator?: User;
}

import axios from 'axios';
import { User, Channel, Video, Comment, Playlist, Report, ModerationAction, VideoAccessGrant } from '../types';

const api = axios.create({
  baseURL: '/api/v1',
});

api.interceptors.request.use((config) => {
  const token = localStorage.getItem('yt_token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

export const apiService = {
  // Auth
  async register(data: any) {
    const res = await api.post('/auth/register', data);
    return res.data;
  },
  async login(email: string, password: string) {
    const res = await api.post('/auth/login', { email, password });
    return res.data;
  },
  async getMe(): Promise<User> {
    const res = await api.get('/auth/me');
    return res.data;
  },

  // Videos
  async getVideos(params?: { search?: string; page?: number; page_size?: number }) {
    const res = await api.get('/videos', { params });
    return res.data;
  },
  async searchVideos(q: string) {
    const res = await api.get('/videos/search', { params: { q } });
    return res.data;
  },
  async getVideo(id: string): Promise<Video> {
    const res = await api.get(`/videos/${id}`);
    return res.data;
  },
  async uploadVideo(formData: FormData) {
    const res = await api.post('/videos/upload', formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
    });
    return res.data;
  },
  async updateVideo(id: string, data: any) {
    const res = await api.patch(`/videos/${id}`, data);
    return res.data;
  },
  async deleteVideo(id: string) {
    await api.delete(`/videos/${id}`);
  },

  // Private Video Grants
  async getGrants(videoId: string): Promise<VideoAccessGrant[]> {
    const res = await api.get(`/videos/${videoId}/grants`);
    return res.data;
  },
  async addGrant(videoId: string, userIdentifier: string) {
    const res = await api.post(`/videos/${videoId}/grants`, { user_identifier: userIdentifier });
    return res.data;
  },
  async revokeGrant(videoId: string, userId: string) {
    await api.delete(`/videos/${videoId}/grants/${userId}`);
  },

  // Reactions
  async toggleReaction(videoId: string, reactionType: 'like' | 'dislike') {
    const res = await api.post(`/videos/${videoId}/reactions`, { reaction_type: reactionType });
    return res.data;
  },

  // Comments
  async getComments(videoId: string): Promise<Comment[]> {
    const res = await api.get(`/videos/${videoId}/comments`);
    return res.data;
  },
  async postComment(videoId: string, content: string): Promise<Comment> {
    const res = await api.post(`/videos/${videoId}/comments`, { content });
    return res.data;
  },
  async deleteComment(commentId: string) {
    await api.delete(`/comments/${commentId}`);
  },

  // Channels & Subscriptions
  async getChannel(channelId: string): Promise<Channel> {
    const res = await api.get(`/channels/${channelId}`);
    return res.data;
  },
  async getChannelVideos(channelId: string): Promise<Video[]> {
    const res = await api.get(`/channels/${channelId}/videos`);
    return res.data;
  },
  async toggleSubscribe(channelId: string) {
    const res = await api.post(`/channels/${channelId}/subscribe`);
    return res.data;
  },

  // Playlists
  async getChannelPlaylists(channelId: string): Promise<Playlist[]> {
    const res = await api.get(`/playlists/channel/${channelId}`);
    return res.data;
  },
  async createPlaylist(data: { title: string; description?: string; visibility?: string }): Promise<Playlist> {
    const res = await api.post('/playlists', data);
    return res.data;
  },
  async getPlaylist(playlistId: string): Promise<Playlist> {
    const res = await api.get(`/playlists/${playlistId}`);
    return res.data;
  },
  async addPlaylistItem(playlistId: string, videoId: string) {
    const res = await api.post(`/playlists/${playlistId}/items`, { video_id: videoId });
    return res.data;
  },

  // Moderation
  async reportVideo(data: { video_id: string; reason: string; details?: string }): Promise<Report> {
    const res = await api.post('/moderation/reports', data);
    return res.data;
  },
  async getReports(): Promise<Report[]> {
    const res = await api.get('/moderation/reports');
    return res.data;
  },
  async hideVideo(videoId: string, reason: string): Promise<ModerationAction> {
    const res = await api.post(`/moderation/videos/${videoId}/hide`, { action: 'hide', reason });
    return res.data;
  },
  async restoreVideo(videoId: string, reason: string): Promise<ModerationAction> {
    const res = await api.post(`/moderation/videos/${videoId}/restore`, { action: 'restore', reason });
    return res.data;
  },
  async getModerationActions(): Promise<ModerationAction[]> {
    const res = await api.get('/moderation/actions');
    return res.data;
  },

  // Users
  async searchUsers(search?: string): Promise<User[]> {
    const res = await api.get('/users', { params: { search } });
    return res.data;
  }
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { User } from '../types';
import { apiService } from '../services/api';

interface AuthContextType {
  user: User | null;
  token: string | null;
  isLoading: boolean;
  login: (email: string, pass: string) => Promise<void>;
  register: (data: any) => Promise<void>;
  logout: () => void;
  switchDemoAccount: (role: 'admin' | 'moderator' | 'creator' | 'viewer') => Promise<void>;
  isAuthModalOpen: boolean;
  openAuthModal: () => void;
  closeAuthModal: () => void;
  isUploadModalOpen: boolean;
  openUploadModal: () => void;
  closeUploadModal: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(localStorage.getItem('yt_token'));
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);

  useEffect(() => {
    const fetchUser = async () => {
      if (token) {
        try {
          const userData = await apiService.getMe();
          setUser(userData);
        } catch (e) {
          console.error("Auth check failed:", e);
          localStorage.removeItem('yt_token');
          setToken(null);
          setUser(null);
        }
      }
      setIsLoading(false);
    };
    fetchUser();
  }, [token]);

  const login = async (email: string, pass: string) => {
    const data = await apiService.login(email, pass);
    localStorage.setItem('yt_token', data.access_token);
    setToken(data.access_token);
    setUser(data.user);
    setIsAuthModalOpen(false);
  };

  const register = async (regData: any) => {
    const data = await apiService.register(regData);
    localStorage.setItem('yt_token', data.access_token);
    setToken(data.access_token);
    setUser(data.user);
    setIsAuthModalOpen(false);
  };

  const logout = () => {
    localStorage.removeItem('yt_token');
    setToken(null);
    setUser(null);
  };

  const switchDemoAccount = async (role: 'admin' | 'moderator' | 'creator' | 'viewer') => {
    const credentials = {
      admin: { email: 'admin@youtube.local', pass: 'AdminPass123!' },
      moderator: { email: 'moderator@youtube.local', pass: 'ModPass123!' },
      creator: { email: 'creator@youtube.local', pass: 'CreatorPass123!' },
      viewer: { email: 'viewer@youtube.local', pass: 'ViewerPass123!' },
    };
    const creds = credentials[role];
    await login(creds.email, creds.pass);
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        token,
        isLoading,
        login,
        register,
        logout,
        switchDemoAccount,
        isAuthModalOpen,
        openAuthModal: () => setIsAuthModalOpen(true),
        closeAuthModal: () => setIsAuthModalOpen(false),
        isUploadModalOpen,
        openUploadModal: () => {
          if (!user) {
            setIsAuthModalOpen(true);
          } else {
            setIsUploadModalOpen(true);
          }
        },
        closeUploadModal: () => setIsUploadModalOpen(false),
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

