import React, { useRef, useState, useEffect } from 'react';
import { Play, Pause, Volume2, VolumeX, Maximize } from 'lucide-react';

interface VideoPlayerProps {
  src: string;
  poster?: string | null;
}

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ src, poster }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(1);
  const [isMuted, setIsMuted] = useState(false);

  const togglePlay = () => {
    if (!videoRef.current) return;
    if (isPlaying) {
      videoRef.current.pause();
    } else {
      videoRef.current.play();
    }
  };

  const handleTimeUpdate = () => {
    if (videoRef.current) {
      setCurrentTime(videoRef.current.currentTime);
      setDuration(videoRef.current.duration || 0);
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const time = parseFloat(e.target.value);
    if (videoRef.current) {
      videoRef.current.currentTime = time;
      setCurrentTime(time);
    }
  };

  const toggleMute = () => {
    if (!videoRef.current) return;
    videoRef.current.muted = !isMuted;
    setIsMuted(!isMuted);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseFloat(e.target.value);
    setVolume(vol);
    if (videoRef.current) {
      videoRef.current.volume = vol;
      videoRef.current.muted = vol === 0;
      setIsMuted(vol === 0);
    }
  };

  const toggleFullscreen = () => {
    if (!videoRef.current) return;
    if (document.fullscreenElement) {
      document.exitFullscreen();
    } else {
      videoRef.current.requestFullscreen();
    }
  };

  const formatTime = (time: number) => {
    const mins = Math.floor(time / 60);
    const secs = Math.floor(time % 60);
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
  };

  return (
    <div className="relative aspect-video w-full bg-black rounded-2xl overflow-hidden group shadow-2xl">
      <video
        ref={videoRef}
        src={src}
        poster={poster || undefined}
        className="w-full h-full object-contain cursor-pointer"
        onClick={togglePlay}
        onPlay={() => setIsPlaying(true)}
        onPause={() => setIsPlaying(false)}
        onTimeUpdate={handleTimeUpdate}
        onLoadedMetadata={handleTimeUpdate}
        controls
      />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Comment } from '../../types';
import { apiService } from '../../services/api';
import { useAuth } from '../../context/AuthContext';
import { Trash2, MessageSquare } from 'lucide-react';

interface VideoCommentsProps {
  videoId: string;
}

export const VideoComments: React.FC<VideoCommentsProps> = ({ videoId }) => {
  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { user, openAuthModal } = useAuth();

  const loadComments = async () => {
    try {
      const data = await apiService.getComments(videoId);
      setComments(data);
    } catch (e) {
      console.error("Failed to load comments:", e);
    }
  };

  useEffect(() => {
    loadComments();
  }, [videoId]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.trim()) return;

    if (!user) {
      openAuthModal();
      return;
    }

    setIsSubmitting(true);
    try {
      const created = await apiService.postComment(videoId, newComment.trim());
      setComments([created, ...comments]);
      setNewComment('');
    } catch (e) {
      console.error("Failed to post comment:", e);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async (commentId: string) => {
    try {
      await apiService.deleteComment(commentId);
      setComments(comments.filter(c => c.id !== commentId));
    } catch (e) {
      console.error("Failed to delete comment:", e);
    }
  };

  return (
    <div className="mt-6 flex flex-col gap-6">
      <div className="flex items-center gap-3">
        <h3 className="text-xl font-bold text-white">{comments.length} Comments</h3>
      </div>

      {/* Comment Input */}
      <div className="flex gap-4">
        {user ? (
          <img
            src={user.avatar_url || `https://api.dicebear.com/7.x/bottts/svg?seed=${user.username}`}
            alt={user.username}
            className="w-10 h-10 rounded-full object-cover shrink-0"
          />
        ) : (
          <div className="w-10 h-10 rounded-full bg-zinc-700 flex items-center justify-center shrink-0 text-zinc-400">
            <MessageSquare size={20} />
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-2">
          <input
            type="text"
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
            placeholder={user ? "Add a comment..." : "Sign in to add a comment"}
            className="w-full bg-transparent border-b border-[#3f3f3f] focus:border-white outline-none py-1.5 text-sm text-white placeholder-zinc-500 transition"
          />
          {newComment && (
            <div className="flex justify-end gap-2 mt-1">
              <button
                type="button"
                onClick={() => setNewComment('')}
                className="px-3 py-1.5 rounded-full hover:bg-zinc-800 text-sm text-zinc-300"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={isSubmitting}
                className="px-4 py-1.5 rounded-full bg-blue-600 hover:bg-blue-700 text-white text-sm font-semibold disabled:opacity-50 transition"
              >
                Comment
              </button>
            </div>
          )}
        </form>
      </div>

      {/* Comments List */}
      <div className="flex flex-col gap-5 mt-2">
        {comments.map((comment) => (
          <div key={comment.id} className="flex gap-4 group">
            <img
              src={comment.user?.avatar_url || `https://api.dicebear.com/7.x/bottts/svg?seed=${comment.user?.username || 'user'}`}
              alt={comment.user?.username}
              className="w-10 h-10 rounded-full object-cover shrink-0"
            />
            <div className="flex-1 flex flex-col">
              <div className="flex items-center gap-2">
                <span className="text-xs font-semibold text-white">
                  @{comment.user?.username || 'user'}
                </span>
                <span className="text-xs text-zinc-400">
                  {new Date(comment.created_at).toLocaleDateString()}
                </span>
              </div>

              <p className="text-sm text-zinc-200 mt-1 whitespace-pre-line">{comment.content}</p>
            </div>

            {comment.can_delete && (
              <button
                onClick={() => handleDelete(comment.id)}
                className="opacity-0 group-hover:opacity-100 p-2 text-zinc-500 hover:text-red-400 transition"
                title="Delete comment"
              >
                <Trash2 size={16} />
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { X, Upload, Film, Image as ImageIcon, Lock, Globe, EyeOff, UserPlus, Check } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { apiService } from '../../services/api';
import { VideoVisibility } from '../../types';

export const VideoUploadModal: React.FC = () => {
  const { isUploadModalOpen, closeUploadModal } = useAuth();
  const navigate = useNavigate();

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [visibility, setVisibility] = useState<VideoVisibility>('public');
  const [videoFile, setVideoFile] = useState<File | null>(null);
  const [thumbnailFile, setThumbnailFile] = useState<File | null>(null);
  const [grantedUser, setGrantedUser] = useState('');
  const [grantedUsersList, setGrantedUsersList] = useState<string[]>([]);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [isUploading, setIsUploading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  if (!isUploadModalOpen) return null;

  const handleAddGrant = (e: React.FormEvent) => {
    e.preventDefault();
    if (grantedUser.trim() && !grantedUsersList.includes(grantedUser.trim())) {
      setGrantedUsersList([...grantedUsersList, grantedUser.trim()]);
      setGrantedUser('');
    }
  };

  const handleRemoveGrant = (username: string) => {
    setGrantedUsersList(grantedUsersList.filter(u => u !== username));
  };

  const handleUpload = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!videoFile) {
      setErrorMsg('Please select a video file.');
      return;
    }
    if (!title.trim()) {
      setErrorMsg('Please enter a video title.');
      return;
    }

    setIsUploading(true);
    setErrorMsg('');
    setUploadProgress(15);

    try {
      const formData = new FormData();
      formData.append('title', title.trim());
      formData.append('description', description.trim());
      formData.append('visibility', visibility);
      formData.append('video_file', videoFile);
      if (thumbnailFile) {
        formData.append('thumbnail_file', thumbnailFile);
      }

      setUploadProgress(60);
      const video = await apiService.uploadVideo(formData);
      setUploadProgress(85);

      // If private and granted users specified, add grants
      if (visibility === 'private' && grantedUsersList.length > 0) {
        for (const u of grantedUsersList) {
          try {
            await apiService.addGrant(video.id, u);
          } catch (err) {
            console.error(`Failed to grant access to ${u}:`, err);
          }
        }
      }

      setUploadProgress(100);
      closeUploadModal();
      navigate(`/watch/${video.id}`);
    } catch (err: any) {
      console.error("Upload error:", err);
      setErrorMsg(err.response?.data?.detail || 'Failed to upload video.');
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
      <div className="relative w-full max-w-2xl bg-[#212121] border border-[#3f3f3f] rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
        {/* Modal Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-[#3f3f3f]">
          <h2 className="text-lg font-bold text-white flex items-center gap-2">
            <Upload size={20} className="text-red-500" />
            Upload Video
          </h2>
          <button
            onClick={closeUploadModal}
            className="p-1 text-zinc-400 hover:text-white rounded-full hover:bg-zinc-800 transition"
          >
            <X size={20} />
          </button>
        </div>

        {/* Modal Body */}
        <form onSubmit={handleUpload} className="p-6 overflow-y-auto space-y-5">
          {errorMsg && (
