    if (!videoId) return;
    setIsLoading(true);
    setErrorStatus(null);
    try {
      const data = await apiService.getVideo(videoId);
      setVideo(data);
      setLikesCount(data.likes_count);
      setDislikesCount(data.dislikes_count);
      setUserReaction(data.user_reaction || null);
      if (data.channel) {
        setIsSubscribed(!!data.channel.is_subscribed);
        setSubscribersCount(data.channel.subscribers_count);
      }

      // Load recommended videos
      const recRes = await apiService.getVideos({ page_size: 10 });
      setRecommended(recRes.items.filter(v => v.id !== videoId));
    } catch (err: any) {
      console.error("Watch load error:", err);
      setErrorStatus({
        status: err.response?.status || 500,
        message: err.response?.data?.detail || 'An error occurred loading the video.'
      });
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadVideo();
  }, [videoId, user]);

  const handleReaction = async (type: 'like' | 'dislike') => {
    if (!user) {
      openAuthModal();
      return;
    }
    if (!videoId) return;
    try {
      const res = await apiService.toggleReaction(videoId, type);
      setUserReaction(res.user_reaction);
      setLikesCount(res.likes_count);
      setDislikesCount(res.dislikes_count);
    } catch (e) {
      console.error("Reaction failed:", e);
    }
  };

  const handleSubscribe = async () => {
    if (!user) {
      openAuthModal();
      return;
    }
    if (!video?.channel) return;
    try {
      const res = await apiService.toggleSubscribe(video.channel.id);
      setIsSubscribed(res.is_subscribed);
      setSubscribersCount(res.subscribers_count);
    } catch (e) {
      console.error("Subscribe toggle failed:", e);
    }
  };

  const handleShare = () => {
    navigator.clipboard.writeText(window.location.href);
    setCopiedLink(true);
    setTimeout(() => setCopiedLink(false), 2000);
  };

  const loadGrants = async () => {
    if (!videoId) return;
    try {
      const g = await apiService.getGrants(videoId);
      setGrants(g);
    } catch (e) {
      console.error("Failed to load grants:", e);
    }
  };

  const handleAddGrant = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!videoId || !grantInput.trim()) return;
    try {
      await apiService.addGrant(videoId, grantInput.trim());
      setGrantInput('');
      loadGrants();
    } catch (e: any) {
      alert(e.response?.data?.detail || "Could not grant access");
    }
  };

  const handleRevokeGrant = async (targetUserId: string) => {
    if (!videoId) return;
    try {
      await apiService.revokeGrant(videoId, targetUserId);
      loadGrants();
    } catch (e) {
      console.error("Revoke failed:", e);
    }
  };

  if (isLoading) {
    return (
      <div className="flex-1 p-6 flex flex-col items-center justify-center">
        <div className="w-12 h-12 border-4 border-red-600 border-t-transparent rounded-full animate-spin" />
        <span className="text-sm text-zinc-400 mt-4">Loading video stream...</span>
      </div>
    );
  }

  if (errorStatus) {
    return (
      <div className="flex-1 p-10 flex flex-col items-center justify-center text-center">
        <div className="w-16 h-16 rounded-full bg-red-950/80 border border-red-500/50 flex items-center justify-center text-red-400 mb-4">
          <AlertCircle size={36} />
        </div>
        <h2 className="text-xl font-bold text-white mb-2">Video Unavailable</h2>
        <p className="text-sm text-zinc-400 max-w-md mb-6">{errorStatus.message}</p>
        {errorStatus.status === 401 && (
          <button
            onClick={openAuthModal}
            className="px-6 py-2.5 rounded-full bg-red-600 hover:bg-red-700 text-white font-semibold text-sm transition"
          >
            Sign in to check permissions
          </button>
        )}
      </div>
    );
  }

  if (!video) return null;

  return (
    <div className="flex-1 overflow-y-auto px-6 py-6 flex flex-col lg:flex-row gap-6">
      {/* Left/Main Column: Video & Metadata */}
      <div className="flex-1 max-w-[1280px]">
        {/* Player */}
        <VideoPlayer
          src={video.video_url}
          poster={video.thumbnail_url}
        />

        {/* Video Title */}
        <h1 className="text-xl font-bold text-white mt-4">{video.title}</h1>

        {/* Action Bar & Channel Info */}
        <div className="flex flex-wrap items-center justify-between gap-4 mt-3 pb-3 border-b border-[#272727]">
          {/* Channel info */}
          <div className="flex items-center gap-3">
            {video.channel && (
              <Link to={`/channel/${video.channel.id}`} className="shrink-0">
                <img
                  src={video.channel.avatar_url || `https://api.dicebear.com/7.x/bottts/svg?seed=${video.channel.name}`}
                  alt={video.channel.name}
                  className="w-10 h-10 rounded-full object-cover"
                />
              </Link>
            )}

            <div className="flex flex-col">
              {video.channel && (
                <Link to={`/channel/${video.channel.id}`} className="font-semibold text-sm text-white hover:text-zinc-300">
                  {video.channel.name}
                </Link>
              )}
              <span className="text-xs text-zinc-400">{subscribersCount} subscribers</span>
            </div>

            {/* Subscribe Button */}
            {video.channel && user?.id !== video.channel.user_id && (
              <button
                onClick={handleSubscribe}
                className={`ml-3 px-4 py-2 rounded-full text-sm font-semibold transition ${
                  isSubscribed
                    ? 'bg-[#272727] text-white hover:bg-[#383838]'
                    : 'bg-white text-black hover:bg-zinc-200'
                }`}
              >
                {isSubscribed ? 'Subscribed' : 'Subscribe'}
              </button>
            )}
          </div>

          {/* Action Buttons: Like, Dislike, Share, Report, Grants */}
          <div className="flex items-center gap-2 flex-wrap">
            {/* Like & Dislike Pills */}
            <div className="flex items-center bg-[#272727] rounded-full overflow-hidden">
              <button
                onClick={() => handleReaction('like')}
                className={`flex items-center gap-1.5 px-3.5 py-2 hover:bg-[#383838] text-sm font-medium transition ${
                  userReaction === 'like' ? 'text-blue-400' : 'text-white'
                }`}
              >
                <ThumbsUp size={16} className={userReaction === 'like' ? 'fill-blue-400' : ''} />
                <span>{likesCount}</span>
              </button>
              <div className="w-[1px] h-6 bg-zinc-600" />
              <button
                onClick={() => handleReaction('dislike')}
                className={`px-3.5 py-2 hover:bg-[#383838] text-sm font-medium transition ${
                  userReaction === 'dislike' ? 'text-red-400' : 'text-white'
                }`}
              >
                <ThumbsDown size={16} className={userReaction === 'dislike' ? 'fill-red-400' : ''} />
              </button>
            </div>

            {/* Share */}
            <button
              onClick={handleShare}
              className="flex items-center gap-1.5 px-3.5 py-2 rounded-full bg-[#272727] hover:bg-[#383838] text-white text-sm font-medium transition"
            >
              <Share2 size={16} />
              <span>{copiedLink ? 'Copied!' : 'Share'}</span>
            </button>

            {/* Private Video Grants Manager (for Owner / Admin) */}
            {video.is_owner && video.visibility === 'private' && (
              <button
                onClick={() => {
                  setShowGrants(!showGrants);
                  if (!showGrants) loadGrants();
                }}
                className="flex items-center gap-1.5 px-3.5 py-2 rounded-full bg-red-950/60 border border-red-600 text-red-200 hover:bg-red-900 text-sm font-medium transition"
              >
                <Lock size={15} />
                <span>Manage Grants</span>
              </button>
            )}

            {/* Report */}
            <button
              onClick={() => setIsReportModalOpen(true)}
              className="p-2 rounded-full bg-[#272727] hover:bg-[#383838] text-zinc-400 hover:text-red-400 transition"
              title="Report Video"
            >
              <Flag size={16} />
            </button>
          </div>
        </div>

        {/* Access Grants Panel if Owner Opened it */}
        {showGrants && (
          <div className="my-4 p-4 bg-[#181818] border border-red-800/50 rounded-xl space-y-3">
            <h3 className="text-sm font-bold text-red-400 uppercase tracking-wider flex items-center gap-2">
              <UserPlus size={16} />
              Private Video Access Grants
            </h3>
            <p className="text-xs text-zinc-400">
              Only users listed below can view this video. Add users by their username:
            </p>

            <form onSubmit={handleAddGrant} className="flex gap-2">
              <input
                type="text"
                value={grantInput}
                onChange={(e) => setGrantInput(e.target.value)}
                placeholder="Enter username (e.g. demo_viewer)"
                className="flex-1 bg-[#121212] border border-[#3f3f3f] rounded-lg px-3 py-1.5 text-sm text-white outline-none"
              />
              <button
                type="submit"
                className="px-4 py-1.5 bg-red-600 hover:bg-red-700 text-white rounded-lg text-sm font-semibold transition"
              >
                Grant Access
              </button>
            </form>

            <div className="space-y-1.5 mt-2">
              {grants.length === 0 ? (
                <span className="text-xs text-zinc-500 italic">No external users granted yet. Only you can watch.</span>
              ) : (
                grants.map((g) => (
                  <div key={g.id} className="flex items-center justify-between p-2 rounded bg-zinc-900 border border-zinc-800 text-xs">
                    <span className="text-zinc-200 font-medium">@{g.user?.username || g.user_id}</span>
                    <button
                      onClick={() => handleRevokeGrant(g.user_id)}
                      className="text-red-400 hover:text-red-300 font-semibold"
                    >
                      Revoke
                    </button>
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {/* Expandable Description Box */}
        <div
          onClick={() => setIsDescriptionExpanded(!isDescriptionExpanded)}
          className="mt-4 p-4 rounded-xl bg-[#272727] hover:bg-[#323232] cursor-pointer transition select-none"
        >
          <div className="flex items-center gap-2 text-sm font-semibold text-white">
            <span>{video.views_count} views</span>
            <span>•</span>
            <span>{new Date(video.created_at).toLocaleDateString()}</span>
          </div>

          <p className={`text-sm text-zinc-200 mt-2 whitespace-pre-line ${
            isDescriptionExpanded ? '' : 'line-clamp-3'
          }`}>
            {video.description || 'No description provided.'}
          </p>

          <span className="text-xs font-semibold text-zinc-400 mt-2 block">
            {isDescriptionExpanded ? 'Show less' : 'Show more'}
          </span>
        </div>

        {/* Comments Section */}
        <VideoComments videoId={video.id} />
      </div>

      {/* Right Column: Recommended Videos */}
      <div className="w-full lg:w-[380px] shrink-0 flex flex-col gap-4">
        <h3 className="font-bold text-base text-white">Related videos</h3>
        {recommended.map((recVideo) => (
          <VideoCard key={recVideo.id} video={recVideo} />
        ))}
      </div>

      {/* Report Modal */}
      <ReportModal
        videoId={video.id}
        isOpen={isReportModalOpen}
        onClose={() => setIsReportModalOpen(false)}
      />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { Channel, Video, Playlist } from '../types';
import { apiService } from '../services/api';
import { useAuth } from '../context/AuthContext';
import { VideoCard } from '../components/video/VideoCard';
import { Video as VideoIcon, ListVideo, Info } from 'lucide-react';

export const ChannelPage: React.FC = () => {
  const { channelId } = useParams<{ channelId: string }>();
  const { user, openAuthModal } = useAuth();

  const [channel, setChannel] = useState<Channel | null>(null);
  const [videos, setVideos] = useState<Video[]>([]);
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [activeTab, setActiveTab] = useState<'videos' | 'playlists' | 'about'>('videos');
  const [isLoading, setIsLoading] = useState(true);

  const [isSubscribed, setIsSubscribed] = useState(false);
  const [subscribersCount, setSubscribersCount] = useState(0);

  const loadChannelData = async () => {
    if (!channelId) return;
    setIsLoading(true);
    try {
      const ch = await apiService.getChannel(channelId);
      setChannel(ch);
      setIsSubscribed(!!ch.is_subscribed);
      setSubscribersCount(ch.subscribers_count);

      const vList = await apiService.getChannelVideos(channelId);
      setVideos(vList);

      const pList = await apiService.getChannelPlaylists(channelId);
      setPlaylists(pList);
    } catch (e) {
      console.error("Failed to load channel:", e);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadChannelData();
  }, [channelId]);

  const handleSubscribe = async () => {
    if (!user) {
      openAuthModal();
      return;
    }
    if (!channel) return;
    try {
      const res = await apiService.toggleSubscribe(channel.id);
      setIsSubscribed(res.is_subscribed);
      setSubscribersCount(res.subscribers_count);
    } catch (e) {
      console.error("Failed subscribe:", e);
    }
  };

  if (isLoading) {
    return (
      <div className="flex-1 p-6 flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-red-600 border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (!channel) {
    return (
      <div className="flex-1 p-10 text-center text-zinc-400">
        Channel not found.
      </div>
    );
  }

  return (
    <div className="flex-1 overflow-y-auto">
      {/* Banner */}
      <div className="w-full h-36 sm:h-52 md:h-64 bg-zinc-800 overflow-hidden relative">
        {channel.banner_url ? (
          <img
            src={channel.banner_url}
            alt={channel.name}
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="w-full h-full bg-gradient-to-r from-red-900 to-zinc-900" />
        )}
      </div>

      {/* Channel Header Meta */}
      <div className="max-w-7xl mx-auto px-6 py-6 border-b border-[#272727]">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-6">
          <div className="flex items-center gap-5">
            <img
              src={channel.avatar_url || `https://api.dicebear.com/7.x/bottts/svg?seed=${channel.name}`}
              alt={channel.name}
              className="w-20 h-20 sm:w-28 sm:h-28 rounded-full object-cover border-4 border-[#0f0f0f]"
            />
            <div className="flex flex-col">
              <h1 className="text-2xl font-bold text-white">{channel.name}</h1>
              <div className="flex items-center gap-2 text-sm text-zinc-400 mt-1">
                <span>{channel.handle}</span>
                <span>•</span>
                <span>{subscribersCount} subscribers</span>
                <span>•</span>
                <span>{videos.length} videos</span>
              </div>
              <p className="text-sm text-zinc-300 mt-2 max-w-2xl line-clamp-2">
                {channel.description || 'Welcome to this channel!'}
              </p>
            </div>
          </div>

          {user?.id !== channel.user_id && (
            <button
              onClick={handleSubscribe}
              className={`px-6 py-2.5 rounded-full font-semibold text-sm transition ${
                isSubscribed
                  ? 'bg-[#272727] text-white hover:bg-[#383838]'
                  : 'bg-white text-black hover:bg-zinc-200'
              }`}
            >
              {isSubscribed ? 'Subscribed' : 'Subscribe'}
            </button>
          )}
        </div>

        {/* Channel Tabs */}
        <div className="flex gap-8 mt-6">
          <button
            onClick={() => setActiveTab('videos')}
            className={`pb-3 font-semibold text-sm flex items-center gap-2 border-b-2 transition ${
              activeTab === 'videos'
                ? 'border-white text-white'
                : 'border-transparent text-zinc-400 hover:text-white'
            }`}
          >
            <VideoIcon size={18} />
            <span>Videos ({videos.length})</span>
          </button>

          <button
            onClick={() => setActiveTab('playlists')}
            className={`pb-3 font-semibold text-sm flex items-center gap-2 border-b-2 transition ${
              activeTab === 'playlists'
                ? 'border-white text-white'
                : 'border-transparent text-zinc-400 hover:text-white'
            }`}
          >
            <ListVideo size={18} />
            <span>Playlists ({playlists.length})</span>
          </button>

          <button
            onClick={() => setActiveTab('about')}
            className={`pb-3 font-semibold text-sm flex items-center gap-2 border-b-2 transition ${
              activeTab === 'about'
                ? 'border-white text-white'
                : 'border-transparent text-zinc-400 hover:text-white'
            }`}
          >
            <Info size={18} />
            <span>About</span>
          </button>
        </div>
      </div>

      {/* Tab Content */}
      <div className="max-w-7xl mx-auto px-6 py-6">
        {activeTab === 'videos' && (
          videos.length === 0 ? (
            <div className="text-center py-16 text-zinc-500">
              No videos uploaded yet on this channel.
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-x-4 gap-y-8">
              {videos.map((v) => (
                <VideoCard key={v.id} video={v} />
              ))}
            </div>
          )
        )}

        {activeTab === 'playlists' && (
          playlists.length === 0 ? (
            <div className="text-center py-16 text-zinc-500">
              No public playlists available.
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {playlists.map((pl) => (
                <div key={pl.id} className="p-4 rounded-xl bg-[#212121] border border-[#272727] flex flex-col gap-2">
                  <div className="aspect-video bg-zinc-800 rounded-lg flex items-center justify-center text-zinc-500">
                    <ListVideo size={36} />
                  </div>
                  <h3 className="font-bold text-white text-base mt-1">{pl.title}</h3>
                  <p className="text-xs text-zinc-400 line-clamp-2">{pl.description || 'Playlist'}</p>
                </div>
              ))}
            </div>
          )
        )}

        {activeTab === 'about' && (
          <div className="max-w-2xl bg-[#212121] p-6 rounded-2xl border border-[#272727] space-y-4">
            <h3 className="text-lg font-bold text-white">About {channel.name}</h3>
            <p className="text-sm text-zinc-300 whitespace-pre-line leading-relaxed">
              {channel.description || 'No detailed description provided.'}
            </p>
            <div className="border-t border-[#303030] pt-4 text-xs text-zinc-400 space-y-1">
              <p>Joined: {new Date(channel.created_at).toLocaleDateString()}</p>
              <p>Total subscribers: {subscribersCount}</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSearchParams, Link } from 'react-router-dom';
import { Video } from '../types';
import { apiService } from '../services/api';
import { Search, Eye } from 'lucide-react';

export const SearchPage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const query = searchParams.get('q') || '';
  const [videos, setVideos] = useState<Video[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const doSearch = async () => {
      setIsLoading(true);
      try {
        const res = await apiService.searchVideos(query);
        setVideos(res.items);
      } catch (e) {
        console.error("Search failed:", e);
      } finally {
        setIsLoading(false);
      }
    };
    if (query) {
      doSearch();
    }
  }, [query]);

  return (
    <div className="flex-1 overflow-y-auto px-6 py-6 max-w-6xl mx-auto">
      <div className="flex items-center gap-2 mb-6 text-sm text-zinc-400">
        <Search size={18} />
        <span>Search results for: <strong className="text-white">"{query}"</strong></span>
      </div>

      {isLoading ? (
        <div className="space-y-4">
          {[...Array(5)].map((_, i) => (
            <div key={i} className="animate-pulse flex flex-col sm:flex-row gap-4">
              <div className="w-full sm:w-80 aspect-video bg-zinc-800 rounded-xl shrink-0" />
              <div className="flex-1 space-y-2 py-2">
                <div className="h-5 bg-zinc-800 rounded w-2/3" />
                <div className="h-4 bg-zinc-800 rounded w-1/3" />
                <div className="h-10 bg-zinc-800 rounded w-full mt-2" />
              </div>
            </div>
          ))}
        </div>
      ) : videos.length === 0 ? (
        <div className="text-center py-20 text-zinc-500">
          <p className="text-lg">No results found matching "{query}"</p>
          <p className="text-sm mt-1">Try different keywords or check spelling.</p>
        </div>
      ) : (
        <div className="flex flex-col gap-5">
          {videos.map((video) => (
            <div key={video.id} className="flex flex-col sm:flex-row gap-4 group cursor-pointer">
              {/* Thumbnail */}
              <Link to={`/watch/${video.id}`} className="relative w-full sm:w-80 aspect-video rounded-xl overflow-hidden bg-zinc-800 shrink-0">
                {video.thumbnail_url ? (
                  <img
                    src={video.thumbnail_url}
                    alt={video.title}
                    className="w-full h-full object-cover group-hover:scale-105 transition duration-300"
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center bg-zinc-900 text-zinc-600">
                    <Eye size={36} />
                  </div>
                )}
                <div className="absolute bottom-2 right-2 bg-black/80 px-1.5 py-0.5 rounded text-[11px] font-semibold text-white">
                  {Math.floor(video.duration / 60)}:{Math.floor(video.duration % 60) < 10 ? '0' : ''}{Math.floor(video.duration % 60)}
                </div>
              </Link>

              {/* Meta */}
              <div className="flex-1 flex flex-col py-1">
                <Link
                  to={`/watch/${video.id}`}
                  className="font-bold text-base text-white group-hover:text-blue-400 transition line-clamp-2"
                >
                  {video.title}
                </Link>

                <div className="flex items-center gap-2 text-xs text-zinc-400 mt-1">
                  <span>{video.views_count} views</span>
                  <span>•</span>
                  <span>{new Date(video.created_at).toLocaleDateString()}</span>
                </div>

                {video.channel && (
                  <Link
                    to={`/channel/${video.channel.id}`}
                    className="flex items-center gap-2 mt-3 hover:text-white transition"
                  >
                    <img
                      src={video.channel.avatar_url || `https://api.dicebear.com/7.x/bottts/svg?seed=${video.channel.name}`}
                      alt={video.channel.name}
                      className="w-6 h-6 rounded-full object-cover"
                    />
                    <span className="text-xs text-zinc-300">{video.channel.name}</span>
                  </Link>
                )}

                <p className="text-xs text-zinc-400 mt-2 line-clamp-2">
                  {video.description || 'No description available.'}
                </p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Playlist } from '../types';
import { apiService } from '../services/api';
import { ListVideo, Film } from 'lucide-react';

export const PlaylistsPage: React.FC = () => {
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const loadPlaylists = async () => {
